function goalTargets(form, tdee) {
  const goal = form.objetivo || '';
  if (!goal) return null;
  const defaultPct = GOALS[goal].pct;
  let pct = form.ajustePct === null || form.ajustePct === undefined
    ? defaultPct : Number(form.ajustePct);
  if (!Number.isFinite(pct)) pct = defaultPct;

  /* El signo lo manda el objetivo, no lo que se haya guardado antes:
     "perder grasa" siempre resta, "ganar músculo" siempre suma.       */
  const magnitud = Math.min(Math.abs(pct), 40);
  if (goal === 'Perder grasa') pct = -magnitud;
  else if (goal === 'Ganar músculo') pct = magnitud;
  else pct = 0;

  const kcal = Math.max(tdee * (1 + pct / 100), 800);
  const peso = Number(form.peso) || 0;

  /* Proteína sobre MASA MAGRA, no sobre peso total.
     En alguien con sobrepeso, 2 g por kilo total da cifras imposibles
     que se comen todo el presupuesto de calorías.                     */
  let magra = peso * 0.75; // respaldo si aún no hay medidas
  try {
    const r = calcAll(form);
    if (r && r.cinta && Number.isFinite(r.leanKg) && r.leanKg > 0) magra = r.leanKg;
  } catch {}

  let protein = magra * 2.2;

  /* Topes de seguridad: la proteína nunca puede pasar del 40% de las
     calorías, ni bajar de 1.6 g por kilo de masa magra.               */
  const maxProtKcal = kcal * 0.40;
  if (protein * 4 > maxProtKcal) protein = maxProtKcal / 4;
  const minProt = magra * 1.6;
  if (protein < minProt) protein = minProt;

  /* Grasa: 25% de las calorías, con piso de 20% (por debajo afecta
     las hormonas).                                                    */
  let fat = (kcal * 0.25) / 9;
  const minFat = (kcal * 0.20) / 9;

  /* Los carbohidratos absorben el resto, con un piso del 12%.
     Si no alcanza, se recortan primero la grasa y luego la proteína,
     para que los tres macros SIEMPRE sumen las calorías objetivo.     */
  const minCarbsKcal = kcal * 0.12;
  let carbsKcal = kcal - protein * 4 - fat * 9;

  if (carbsKcal < minCarbsKcal) {
    const falta = minCarbsKcal - carbsKcal;
    const puedeGrasa = Math.max(fat * 9 - minFat * 9, 0);
    const recorteGrasa = Math.min(falta, puedeGrasa);
    fat -= recorteGrasa / 9;
    const resto = falta - recorteGrasa;
    if (resto > 0) protein = Math.max(protein - resto / 4, magra * 1.2);
    carbsKcal = kcal - protein * 4 - fat * 9;
  }

  const carbs = Math.max(carbsKcal / 4, 0);

  /* Ajuste final: si por redondeos algo no cuadra, la grasa absorbe
     la diferencia para que la suma sea exacta.                        */
  const suma = protein * 4 + carbs * 4 + fat * 9;
  const dif = kcal - suma;
  if (Math.abs(dif) > 1) fat = Math.max(fat + dif / 9, minFat * 0.9);

  return { goal, pct, kcal, protein, carbs, fat, magra };
}

/* Meta del registro de comidas (calorías y % de macros) a partir de los
   resultados de goalTargets. metaManual en false: vuelve a seguir al
   objetivo aunque antes la hubiera ajustado a mano.                    */
function metaDesdeObjetivo(t) {
  return {
    targetKcal: Math.round(t.kcal),
    macros: {
      p: Math.round((t.protein * 4 / t.kcal) * 100) / 100,
      c: Math.round((t.carbs * 4 / t.kcal) * 100) / 100,
      f: Math.round((t.fat * 9 / t.kcal) * 100) / 100,
    },
    metaManual: false,
  };
}

function GoalSelector({ form, setForm, tdee, peso, datosListos = true, onCompletarDatos, onIrComidas }) {
  const goal = form.objetivo || '';
  const defaultPct = goal ? GOALS[goal].pct : 0;
  let pct = form.ajustePct === null || form.ajustePct === undefined ? defaultPct : Number(form.ajustePct);
  if (!Number.isFinite(pct)) pct = defaultPct;
  const mag = Math.min(Math.abs(pct), 40);
  pct = goal === 'Perder grasa' ? -mag : goal === 'Ganar músculo' ? mag : 0;

  function pickGoal(g) {
    setForm(v => ({ ...v, objetivo: g, ajustePct: GOALS[g].pct }));
  }

  const t = goalTargets(form, tdee);
  const targetKcal = t ? t.kcal : 0;
  const proteinG = t ? t.protein : 0;
  const fatG = t ? t.fat : 0;
  const carbsG = t ? t.carbs : 0;

  return (
    <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-5">
      <AyudaTab id="objetivo" texto="Elige qué quieres lograr y la app calcula cuántas calorías y proteína necesitas al día. Puedes ajustar el porcentaje si un profesional te indica otro." />
      <h2 className="jb-display text-base text-zinc-200 mb-1">🎯 ¿CUÁL ES TU OBJETIVO?</h2>
      <p className="jb-body text-xs text-zinc-500 mb-4">Elige uno y calculamos tus calorías y macros diarios.</p>

      {!datosListos && (
        <div className="bg-orange-950/30 border border-orange-500/40 rounded-xl p-4 mb-4">
          <p className="jb-body text-sm text-zinc-200 mb-3">Para calcular tus calorías primero necesito tu edad, estatura y peso. Toma 30 segundos.</p>
          <button onClick={onCompletarDatos} className={btnPrimary + ' w-full'}>
            Completar mis datos básicos <ChevronRight size={16} />
          </button>
        </div>
      )}

      <div className="grid sm:grid-cols-3 gap-3">
        {Object.entries(GOALS).map(([name, g]) => (
          <button key={name} onClick={() => pickGoal(name)}
            className={`rounded-xl p-4 text-left transition-all border ${goal === name ? 'bg-orange-500 border-orange-500 text-zinc-950 scale-[1.02]' : 'bg-zinc-950 border-zinc-800 hover:border-orange-500 text-zinc-100'}`}>
            <div className={`w-10 h-10 rounded-full flex items-center justify-center text-lg mb-2 ${goal === name ? 'bg-zinc-950/15' : 'bg-zinc-800'}`}>
              {g.emoji}
            </div>
            <div className="jb-display text-sm">{name.toUpperCase()}</div>
            <div className={`jb-body text-[11px] mt-0.5 ${goal === name ? 'text-zinc-800' : 'text-zinc-500'}`}>{g.desc}</div>
          </button>
        ))}
      </div>

      {goal && datosListos && (
        <div className="mt-5 flex flex-col gap-4">
          <div>
            <span className="text-xs uppercase tracking-wider text-zinc-400 jb-body block mb-1.5">
              {goal === 'Perder grasa' ? 'Cuánto quieres bajar de tu mantenimiento'
                : goal === 'Ganar músculo' ? 'Cuánto quieres subir de tu mantenimiento'
                : 'Ajuste sobre tu mantenimiento'}
            </span>

            {goal === 'Mantener peso' ? (
              <p className="jb-body text-sm text-zinc-400">
                Comes lo mismo que gastas: {Math.round(tdee)} kcal al día.
              </p>
            ) : (
              <>
                <div className="flex flex-wrap gap-2 mb-3">
                  {[10, 15, 20, 25].map(n => {
                    const valor = goal === 'Perder grasa' ? -n : n;
                    const activo = Math.abs(pct) === n;
                    return (
                      <button key={n}
                        onClick={() => setForm(v => ({ ...v, ajustePct: valor }))}
                        className={`jb-body text-sm px-4 py-2 rounded-lg transition-colors ${activo
                          ? 'bg-orange-500 text-zinc-950 font-semibold'
                          : 'bg-zinc-950 text-zinc-300 border border-zinc-800 hover:border-orange-500'}`}>
                        {goal === 'Perder grasa' ? '−' : '+'}{n}%
                      </button>
                    );
                  })}
                </div>

                <div className="flex items-center gap-2 flex-wrap">
                  <span className="jb-body text-xs text-zinc-500">O escribe otro valor:</span>
                  <div className="flex items-center gap-1.5">
                    <span className="jb-display text-lg text-orange-500">
                      {goal === 'Perder grasa' ? '−' : '+'}
                    </span>
                    <input type="number" inputMode="numeric" min="0" max="40"
                      className={inputCls + ' w-20 py-2'}
                      value={Math.abs(pct) || ''}
                      onChange={e => {
                        const n = Math.min(Math.abs(Number(e.target.value) || 0), 40);
                        setForm(v => ({ ...v, ajustePct: goal === 'Perder grasa' ? -n : n }));
                      }} />
                    <span className="jb-body text-sm text-zinc-400">%</span>
                  </div>
                </div>
              </>
            )}

            <p className="jb-body text-xs text-zinc-500 mt-2">
              {goal === 'Perder grasa'
                ? `Recomendado: −${Math.abs(GOALS[goal].pct)}%. Más de −25% es difícil de sostener.`
                : goal === 'Ganar músculo'
                  ? `Recomendado: +${GOALS[goal].pct}%. Más de +20% suele ganar grasa además de músculo.`
                  : ''}
            </p>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            <StatCard label="Calorías objetivo" value={Math.round(targetKcal)} sub="kcal/día" accent="text-amber-400" />
            <StatCard label="Proteína" value={Math.round(proteinG) + ' g'} sub="según tu masa magra" />
            <StatCard label="Carbos" value={Math.round(Math.max(carbsG, 0)) + ' g'} />
            <StatCard label="Grasas" value={Math.round(fatG) + ' g'} sub="~25% de las calorías" />
          </div>

          <div className="bg-amber-950/40 border border-amber-800/50 rounded-xl p-3 flex gap-2">
            <AlertTriangle className="text-amber-500 shrink-0" size={16} />
            <p className="text-amber-200 text-xs jb-body">Estos valores son una estimación de referencia, no una prescripción médica. Consúltalo con un profesional de la salud antes de aplicarlo.</p>
          </div>

          {onIrComidas && (
            <button onClick={onIrComidas} className={btnPrimary + ' w-full'}>
              🍽️ Ir a registrar mis comidas <ChevronRight size={16} />
            </button>
          )}
        </div>
      )}
    </div>
  );
}

function CuerpoTab({ form, setForm, results, vistaInicial, onIrComidas, mealPlan, setMealPlan }) {
  const [vista, setVista] = useState(vistaInicial === 'objetivo' ? 'objetivo' : 'composicion');

  return (
    <div className="flex flex-col gap-6 min-w-0">
      <div className="flex gap-2">
        <button onClick={() => setVista('composicion')}
          className={`jb-display text-xs px-3 py-1.5 rounded-lg flex items-center gap-1.5 transition-colors ${vista === 'composicion' ? 'bg-orange-500 text-zinc-950 font-semibold' : 'bg-zinc-900 text-zinc-400 border border-zinc-800'}`}>
          <Flame size={13} /> Mis datos
        </button>
        <button onClick={() => setVista('objetivo')}
          className={`jb-display text-xs px-3 py-1.5 rounded-lg flex items-center gap-1.5 transition-colors ${vista === 'objetivo' ? 'bg-orange-500 text-zinc-950 font-semibold' : 'bg-zinc-900 text-zinc-400 border border-zinc-800'}`}>
          <Target size={13} /> Objetivo
        </button>
      </div>
      {vista === 'composicion'
        ? <CalculatorTab form={form} setForm={setForm} results={results}
            onSiguiente={() => { if (form.objetivo) onIrComidas?.(); else setVista('objetivo'); window.scrollTo({ top: 0 }); }} />
        : <GoalSelector form={form} setForm={setForm} tdee={results.tdee} peso={form.peso}
            datosListos={results.basicos}
            onCompletarDatos={() => { setVista('composicion'); window.scrollTo({ top: 0 }); }}
            onIrComidas={onIrComidas} />}
      {vista === 'objetivo' && mealPlan && setMealPlan && (
        <ObjetivoDiarioCard mealPlan={mealPlan} setMealPlan={setMealPlan}
          targets={goalTargets(form, results.tdee)} tdee={results.tdee} />
      )}
    </div>
  );
}

// Campo numérico con − / + grandes; también se puede tocar el número y
// escribirlo. Si está vacío, el primer + / − parte de un valor típico.
function CampoNumero({ label, valor, onCambio, paso = 1, min = 0, max = 999, inicial, unidad, placeholder, ayuda }) {
  const n = Number(valor);
  const vacio = valor === '' || valor === null || valor === undefined || !Number.isFinite(n) || n === 0;
  const decimales = paso < 1 ? 1 : 0;
  const mover = (dir) => {
    vibrar(8);
    const base = vacio ? (inicial ?? min) : n;
    const nuevo = vacio ? base : Math.round((base + dir * paso) / paso) * paso;
    onCambio(Math.min(max, Math.max(min, Number(nuevo.toFixed(decimales)))));
  };
  return (
    <div className="bg-zinc-950 border border-zinc-800 rounded-2xl px-3 pt-2.5 pb-3">
      <div className="flex items-center justify-between mb-1.5">
        <span className="jb-body text-[11px] uppercase tracking-wider text-zinc-400">{label}</span>
        {ayuda && (
          <a href={ayuda} target="_blank" rel="noopener noreferrer" className="jb-body text-[11px] text-orange-400 underline">¿Cómo medir?</a>
        )}
      </div>
      <div className="flex items-center gap-2">
        <BotonPaso etiqueta={`Menos ${label}`} onClick={() => mover(-1)}>−</BotonPaso>
        <div className="flex-1 min-w-0 flex items-baseline justify-center gap-1">
          <input type="number" inputMode={decimales ? 'decimal' : 'numeric'} value={vacio ? '' : valor} placeholder={placeholder}
            onChange={e => onCambio(e.target.value === '' ? '' : Number(e.target.value))}
            className="w-full min-w-0 bg-transparent text-center jb-display text-3xl text-zinc-50 placeholder:text-zinc-700 focus:outline-none tabular-nums [appearance:textfield] [&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none" />
        </div>
        <BotonPaso etiqueta={`Más ${label}`} onClick={() => mover(1)}>+</BotonPaso>
      </div>
      <p className="jb-body text-[11px] text-zinc-500 text-center mt-0.5">{unidad}</p>
    </div>
  );
}

function CalculatorTab({ form, setForm, results, onSiguiente }) {
  const [cintaAbierta, setCintaAbierta] = useState(!!results.cinta);
  const fijar = (k) => (v) => setForm(f => ({ ...f, [k]: v }));
  const faltan = [['edad', 'edad'], ['estatura', 'estatura'], ['peso', 'peso']]
    .filter(([k]) => !(Number(form[k]) > 0)).map(([, n]) => n);
  const esMujer = form.sexo === 'F';

  return (
    <div className="flex flex-col gap-5 min-w-0 max-w-2xl">
      <style>{ESTILOS_COMIDAS}</style>

      {/* Tablero: lo que su cuerpo gasta y cómo está hoy */}
      {results.basicos ? (
        <div className="relative bg-zinc-900 border border-orange-500/30 rounded-3xl p-5 overflow-hidden"
          style={{ boxShadow: '0 0 40px -12px rgba(232,89,12,.35)' }}>
          <div className="absolute -top-16 -right-16 w-48 h-48 rounded-full pointer-events-none"
            style={{ background: 'radial-gradient(circle, rgba(232,89,12,.18), transparent 70%)' }} />
          <p className="relative jb-body text-[11px] text-zinc-500 uppercase tracking-wider mb-1">Tu cuerpo gasta al día</p>
          <p className="relative jb-display text-5xl text-zinc-50 leading-none tabular-nums mb-1">
            <AnimatedNumber value={Math.round(results.tdee)} /><span className="text-lg text-zinc-400 ml-1.5">kcal</span>
          </p>
          <p className="relative jb-body text-xs text-zinc-400 mb-4">
            para mantener tu peso · en reposo quemas <span className="text-zinc-200 font-semibold">{Math.round(results.tmb)} kcal</span>
          </p>
          <div className="relative grid grid-cols-3 gap-2">
            <div className="bg-zinc-950/70 border border-zinc-800 rounded-xl px-2 py-2.5 text-center">
              <p className="jb-display text-xl text-orange-500 tabular-nums leading-none">{results.bmi.toFixed(1)}</p>
              <p className="jb-body text-[10px] text-zinc-400 leading-tight mt-1">IMC · {results.bmiCat}</p>
            </div>
            <button type="button" onClick={() => setCintaAbierta(true)}
              className="bg-zinc-950/70 border border-zinc-800 rounded-xl px-2 py-2.5 text-center">
              <p className="jb-display text-xl text-orange-500 tabular-nums leading-none">{results.cinta ? results.bf.toFixed(1) + '%' : '—'}</p>
              <p className="jb-body text-[10px] text-zinc-400 leading-tight mt-1">{results.cinta ? `grasa · ${results.bfCat}` : 'grasa · mídela con cinta'}</p>
            </button>
            <div className="bg-zinc-950/70 border border-zinc-800 rounded-xl px-2 py-2.5 text-center">
              <p className="jb-display text-xl text-orange-500 tabular-nums leading-none">{results.idealMin.toFixed(0)}–{results.idealMax.toFixed(0)}</p>
              <p className="jb-body text-[10px] text-zinc-400 leading-tight mt-1">kg peso saludable</p>
            </div>
          </div>
        </div>
      ) : (
        <div className="bg-zinc-900 border border-dashed border-orange-500/40 rounded-3xl p-5 text-center">
          <div className="text-3xl mb-2">🔥</div>
          <p className="jb-display text-lg text-zinc-100 mb-1">3 DATOS Y LISTO</p>
          <p className="jb-body text-sm text-zinc-400">Con tu edad, estatura y peso calculamos cuánto gasta tu cuerpo al día. Sin cinta métrica.</p>
        </div>
      )}

      {/* Datos básicos */}
      <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4 min-w-0">
        <h2 className="jb-display text-base text-zinc-200 mb-3">TUS DATOS</h2>
        <div className="grid grid-cols-2 gap-2 mb-3">
          {[['M', 'Hombre'], ['F', 'Mujer']].map(([v, l]) => (
            <button key={v} type="button" onClick={() => setForm(f => ({ ...f, sexo: v }))}
              className={`jb-body text-sm rounded-xl py-2.5 border transition-colors ${form.sexo === v
                ? 'bg-orange-500 border-orange-500 text-zinc-950 font-semibold' : 'bg-zinc-950 border-zinc-800 text-zinc-400'}`}>
              {l}
            </button>
          ))}
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-2 mb-3">
          <CampoNumero label="Edad" valor={form.edad} onCambio={fijar('edad')} paso={1} min={12} max={99} inicial={30} unidad="años" placeholder="30" />
          <CampoNumero label="Estatura" valor={form.estatura} onCambio={fijar('estatura')} paso={1} min={120} max={220} inicial={esMujer ? 158 : 168} unidad="centímetros" placeholder={esMujer ? '158' : '168'} />
          <CampoNumero label="Peso" valor={form.peso} onCambio={fijar('peso')} paso={0.5} min={30} max={250} inicial={esMujer ? 62 : 75} unidad="kilos" placeholder={esMujer ? '62' : '75'} />
        </div>
        <p className="jb-body text-[11px] uppercase tracking-wider text-zinc-400 mb-2">Actividad física</p>
        <div className="flex flex-wrap gap-2 mb-2">
          {Object.keys(ACTIVITY_FACTORS).map(a => (
            <button key={a} type="button" onClick={() => setForm(f => ({ ...f, actividad: a }))}
              className={`jb-body text-xs px-3 py-2 rounded-full border transition-colors ${form.actividad === a
                ? 'bg-orange-500 border-orange-500 text-zinc-950 font-semibold' : 'bg-zinc-950 border-zinc-800 text-zinc-400'}`}>
              {a}
            </button>
          ))}
        </div>
        <p className="jb-body text-xs text-zinc-500 mb-4">{ACTIVITY_DESC[form.actividad] || ''}</p>
        {results.basicos ? (
          <button onClick={onSiguiente} className={btnPrimary + ' w-full py-3'}>
            {form.objetivo ? 'Listo · Registrar mis comidas' : 'Guardar y elegir mi objetivo'} <ChevronRight size={16} />
          </button>
        ) : (
          <p className="jb-body text-xs text-zinc-500 text-center">
            {faltan.length ? `Completa tu ${faltan.length > 1 ? faltan.slice(0, -1).join(', ') + ' y ' + faltan[faltan.length - 1] : faltan[0]} para seguir.` : 'Revisa que tu estatura esté en centímetros (ej. 165).'}
          </p>
        )}
      </div>

      {/* Cinta métrica (opcional) */}
      <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4 min-w-0">
        <button type="button" onClick={() => setCintaAbierta(v => !v)} className="w-full flex items-center justify-between gap-3 text-left">
          <div>
            <h2 className="jb-display text-base text-zinc-200">📏 TU % DE GRASA <span className="text-zinc-500 text-xs">· OPCIONAL</span></h2>
            <p className="jb-body text-xs text-zinc-500">Con una cinta métrica: cuello, cintura y cadera.</p>
          </div>
          <ChevronRight size={18} className={`text-zinc-500 shrink-0 transition-transform ${cintaAbierta ? 'rotate-90' : ''}`} />
        </button>
        {cintaAbierta && (
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-2 mt-4">
            <CampoNumero label="Cuello" valor={form.cuello} onCambio={fijar('cuello')} paso={0.5} min={20} max={70} inicial={esMujer ? 33 : 38} unidad="centímetros" placeholder={esMujer ? '33' : '38'} ayuda="/guia-cuello.jpg" />
            <CampoNumero label="Cintura" valor={form.cintura} onCambio={fijar('cintura')} paso={0.5} min={40} max={200} inicial={esMujer ? 78 : 88} unidad="centímetros" placeholder={esMujer ? '78' : '88'} ayuda="/guia-cintura.jpg" />
            <CampoNumero label="Cadera" valor={form.cadera} onCambio={fijar('cadera')} paso={0.5} min={50} max={200} inicial={esMujer ? 98 : 98} unidad="centímetros" placeholder="98" ayuda="/guia-cadera.jpg" />
          </div>
        )}
      </div>

      {results.basicos && (
        <>
          <div className="grid grid-cols-2 gap-3">
            <StatCard label="Agua corporal est." value={results.water.toFixed(1) + ' L'} />
            {results.cinta && (
              <>
                <StatCard label="Masa grasa" value={results.fatKg.toFixed(1) + ' kg'} />
                <StatCard label="Masa magra" value={results.leanKg.toFixed(1) + ' kg'} />
                <StatCard label="Masa muscular est." value={results.muscleKg.toFixed(1) + ' kg'} />
                {Number(form.cadera) >= 40 && (
                  <StatCard label="Relación cintura-cadera" value={results.iccVal.toFixed(2)} sub={results.iccCat} />
                )}
              </>
            )}
          </div>
          <div className="bg-amber-950/40 border border-amber-800/50 rounded-xl p-3 flex gap-2">
            <AlertTriangle className="text-amber-500 shrink-0" size={16} />
            <p className="text-amber-200 text-xs jb-body">El IMC no distingue grasa de músculo: una persona muy musculosa puede salir "sobrepeso" sin serlo. Úsalo junto al % de grasa corporal.</p>
          </div>
          <p className="jb-body text-[11px] text-zinc-600 text-center">
            Cálculos basados en fórmulas de composición corporal (Navy) y gasto calórico (Mifflin-St Jeor)
          </p>
        </>
      )}
    </div>
  );
}

function RenewalBanner({ user, onRenovar }) {
  if (!user || user.plan === 'trial') return null;
  const dl = daysLeft(user.fechaVencimiento);
  if (dl === null || dl > 7) return null;

  const vencido = dl < 0;
  const hoy = dl === 0;
  const waUrl = `https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(
    `Hola, soy ${user.nombre || user.username} y quiero renovar mi plan de Jonah Beast Fuel.`)}`;

  return (
    <div className={`relative rounded-2xl p-4 pl-5 mb-6 border overflow-hidden ${vencido || hoy
      ? 'bg-orange-950/40 border-orange-500/60' : 'bg-amber-950/30 border-amber-700/50'}`}>
      <div className={`absolute left-0 top-0 bottom-0 w-1.5 ${vencido || hoy ? 'bg-orange-500' : 'bg-amber-500'}`} />
      <div className="flex items-start gap-3">
        <div className={`w-9 h-9 rounded-full flex items-center justify-center shrink-0 ${vencido || hoy ? 'bg-orange-500' : 'bg-amber-500'}`}>
          <CreditCard className="text-zinc-950" size={17} />
        </div>
        <div className="flex-1">
          <p className={`jb-display text-sm mb-1 ${vencido || hoy ? 'text-orange-400' : 'text-amber-400'}`}>
            {vencido ? 'TU PLAN VENCIÓ' : hoy ? 'TU PLAN VENCE HOY' : `TU PLAN VENCE EN ${dl} DÍA${dl > 1 ? 'S' : ''}`}
          </p>
          <p className="jb-body text-sm text-zinc-300">
            {vencido
              ? 'Renueva para seguir registrando tus comidas y no perder el seguimiento de tu progreso.'
              : 'Renueva ahora y sigue sin interrupciones. Tu historial y tus fotos se mantienen intactos.'}
          </p>
          <div className="flex gap-2 mt-3 flex-wrap">
            <button onClick={onRenovar} className={btnPrimary + ' py-2 px-4 text-sm'}>
              Renovar mi plan
            </button>
            <a href={waUrl} target="_blank" rel="noopener noreferrer" className={btnGhost + ' py-2 px-4 text-sm'}>
              <MessageCircle size={14} /> Consultar
            </a>
          </div>
        </div>
      </div>
    </div>
  );
}

// Estado de las notificaciones en este equipo: 'activo', 'disponible'
// (se pueden pedir), 'bloqueado', 'iosNoInstalado' o 'nosoportado'.
async function estadoPushEquipo() {
  const ua = window.navigator.userAgent || '';
  const esIOS = /iPad|iPhone|iPod/.test(ua) && !window.MSStream;
  const instalada = window.matchMedia('(display-mode: standalone)').matches
    || window.navigator.standalone === true;
  if (!('Notification' in window) || !('serviceWorker' in navigator) || !('PushManager' in window)) {
    return esIOS && !instalada ? 'iosNoInstalado' : 'nosoportado';
  }
  if (Notification.permission === 'denied') return 'bloqueado';
  try {
    const reg = await navigator.serviceWorker.ready;
    const sub = await reg.pushManager.getSubscription();
    return sub ? 'activo' : 'disponible';
  } catch { return 'disponible'; }
}

// Estado de avisos del equipo -> palabra que se guarda en la ficha del
// alumno (columna estado_avisos), para que Jonah sepa por qué alguien no
// recibe recordatorios.
const ESTADO_AVISOS_DB = {
  activo: 'activo', iosNoInstalado: 'iphone_sin_instalar', bloqueado: 'bloqueado',
  disponible: 'no_activados', nosoportado: 'no_compatible',
};

function anotarEstadoAvisos(estado) {
  const valor = ESTADO_AVISOS_DB[estado];
  if (!valor) return;
  supabase.rpc('registrar_estado_avisos', { p_estado: valor }).then(() => {}, () => {});
}

// Pide el permiso del navegador, crea la suscripción y la guarda para
// el alumno. Devuelve el estado final ('activo', 'bloqueado' o 'disponible').
async function activarPushAlumno(username) {
  const final = await activarPushAlumnoInterno(username);
  anotarEstadoAvisos(final);
  return final;
}

async function activarPushAlumnoInterno(username) {
  const permiso = await Notification.requestPermission();
  if (permiso !== 'granted') return permiso === 'denied' ? 'bloqueado' : 'disponible';
  const reg = await navigator.serviceWorker.ready;
  let sub = await reg.pushManager.getSubscription();
  if (!sub) {
    sub = await reg.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: base64ToUint8(VAPID_PUBLIC),
    });
  }
  const j = sub.toJSON();
  await supabase.from('push_subs').upsert({
    username, endpoint: j.endpoint, p256dh: j.keys.p256dh, auth: j.keys.auth, activa: true,
  }, { onConflict: 'endpoint' });
  return 'activo';
}

// Después de registrar una comida es el mejor momento para ofrecer los
// recordatorios: el alumno ya vio para qué sirve la app. Antes solo se
// pedían en la bienvenida, y el banner del inicio no se ve durante la
// prueba gratis (ahí va el de la prueba). Se ofrece una sola vez.
function NotifTrasComidaModal({ username, onClose }) {
  const [trabajando, setTrabajando] = useState(false);
  const [resultado, setResultado] = useState(null);

  async function activar() {
    setTrabajando(true);
    let estado = 'disponible';
    try { estado = await activarPushAlumno(username); } catch {}
    setTrabajando(false);
    if (estado === 'activo') { setResultado('activo'); setTimeout(onClose, 1800); }
    else if (estado === 'bloqueado') setResultado('bloqueado');
    else onClose();
  }

  return (
    <div className="fixed inset-0 bg-black/80 flex items-center justify-center p-4 z-50">
      <div className="bg-zinc-900 border border-orange-500/40 rounded-2xl max-w-sm w-full p-6 text-center">
        <div className="w-16 h-16 rounded-full bg-orange-500/15 border border-orange-500/30 flex items-center justify-center text-4xl mx-auto mb-3">
          {resultado === 'activo' ? '✅' : '🦍'}
        </div>
        {resultado === 'activo' ? (
          <h2 className="jb-display text-xl text-zinc-50">¡LISTO! TE AVISARÉ</h2>
        ) : resultado === 'bloqueado' ? (
          <>
            <h2 className="jb-display text-xl text-zinc-50 mb-3">ESTÁN BLOQUEADAS</h2>
            <p className="jb-body text-sm text-zinc-300 mb-5">Tu navegador bloqueó las notificaciones de esta página. Puedes activarlas en los ajustes del navegador cuando quieras.</p>
            <button onClick={onClose} className={btnPrimary + ' w-full'}>Entendido</button>
          </>
        ) : (
          <>
            <h2 className="jb-display text-xl text-zinc-50 mb-3">¡COMIDA REGISTRADA! 💪</h2>
            <p className="jb-body text-sm text-zinc-300 mb-2">
              ¿Activamos tus avisos? Solo lo importante, sin spam:
            </p>
            <ul className="mb-5 flex flex-col gap-1 text-left">
              {BENEFICIOS_AVISOS.map(([e, t]) => (
                <li key={t} className="jb-body text-xs text-zinc-300 flex items-start gap-2"><span>{e}</span><span>{t}</span></li>
              ))}
            </ul>
            <button onClick={activar} disabled={trabajando} className={btnPrimary + ' w-full mb-2'}>
              {trabajando ? <Loader2 className="animate-spin" size={18} /> : '🔔 Sí, activar avisos'}
            </button>
            <button onClick={onClose} className="jb-body text-sm text-zinc-500 hover:text-zinc-300 w-full py-2">
              Ahora no
            </button>
          </>
        )}
      </div>
    </div>
  );
}

