// Fecha corta para gráficos: "24 set".
function fechaCorta(iso) {
  try { return new Date(String(iso).slice(0, 10) + 'T12:00:00').toLocaleDateString('es-PE', { day: 'numeric', month: 'short' }).replace('.', ''); }
  catch { return String(iso).slice(5, 10); }
}

// Gráfico del peso: una sola serie en naranja, la meta como línea
// punteada, el último valor marcado y el detalle de cada día al tocar.
function GraficoPeso({ puntos, meta }) {
  const [activo, setActivo] = useState(null);
  const pts = (puntos || []).filter(p => Number.isFinite(p.v));
  if (pts.length < 2) return <p className="jb-body text-xs text-zinc-500 py-8 text-center">Registra tu peso al menos 2 días para ver tu tendencia.</p>;
  const W = 320, H = 150, PX = 10, PT = 16, PB = 20;
  const vals = pts.map(p => p.v).concat(Number.isFinite(meta) && meta > 0 ? [meta] : []);
  let min = Math.min(...vals), max = Math.max(...vals);
  const margen = Math.max(0.5, (max - min) * 0.12); min -= margen; max += margen;
  const x = i => PX + (i / (pts.length - 1)) * (W - PX * 2);
  const y = v => PT + (1 - (v - min) / (max - min)) * (H - PT - PB);
  const linea = pts.map((p, i) => `${x(i).toFixed(1)},${y(p.v).toFixed(1)}`).join(' ');
  const area = `M${x(0)},${H - PB} L${linea.split(' ').join(' L')} L${x(pts.length - 1)},${H - PB} Z`;
  const ultimo = pts[pts.length - 1];
  const sel = activo !== null ? pts[activo] : null;

  function mover(e) {
    const r = e.currentTarget.getBoundingClientRect();
    const fx = ((e.clientX - r.left) / r.width) * W;
    const i = Math.round(((fx - PX) / (W - PX * 2)) * (pts.length - 1));
    setActivo(Math.max(0, Math.min(pts.length - 1, i)));
  }

  return (
    <div className="relative">
      <svg viewBox={`0 0 ${W} ${H}`} className="w-full h-40 touch-none" onPointerMove={mover} onPointerDown={mover} onPointerLeave={() => setActivo(null)}>
        <defs>
          <linearGradient id="jb-peso-area" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#E8590C" stopOpacity="0.28" />
            <stop offset="100%" stopColor="#E8590C" stopOpacity="0" />
          </linearGradient>
        </defs>
        <line x1={PX} x2={W - PX} y1={H - PB} y2={H - PB} stroke="#2a211a" strokeWidth="1" />
        {Number.isFinite(meta) && meta > 0 && (
          <g>
            <line x1={PX} x2={W - PX} y1={y(meta)} y2={y(meta)} stroke="#a8a29e" strokeWidth="1" strokeDasharray="4 4" vectorEffect="non-scaling-stroke" />
            <text x={W - PX} y={y(meta) - 4} textAnchor="end" fontSize="9" fill="#a8a29e" fontFamily="Work Sans">Meta {meta} kg</text>
          </g>
        )}
        <path d={area} fill="url(#jb-peso-area)" />
        <polyline points={linea} fill="none" stroke="#E8590C" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" vectorEffect="non-scaling-stroke" />
        <circle cx={x(pts.length - 1)} cy={y(ultimo.v)} r="4" fill="#E8590C" stroke="#16110D" strokeWidth="2" />
        {!sel && (
          <text x={x(pts.length - 1) - 6} y={y(ultimo.v) - 8} textAnchor="end" fontSize="10" fontWeight="600" fill="#f5efe6" fontFamily="Work Sans">{ultimo.v.toFixed(1)} kg</text>
        )}
        {sel && (
          <g>
            <line x1={x(activo)} x2={x(activo)} y1={PT - 6} y2={H - PB} stroke="#78716c" strokeWidth="1" vectorEffect="non-scaling-stroke" />
            <circle cx={x(activo)} cy={y(sel.v)} r="4.5" fill="#E8590C" stroke="#16110D" strokeWidth="2" />
          </g>
        )}
        <text x={PX} y={H - 6} fontSize="9" fill="#78716c" fontFamily="Work Sans">{fechaCorta(pts[0].fecha)}</text>
        <text x={W - PX} y={H - 6} textAnchor="end" fontSize="9" fill="#78716c" fontFamily="Work Sans">{fechaCorta(ultimo.fecha)}</text>
      </svg>
      {sel && (
        <div className="absolute top-0 pointer-events-none bg-zinc-950 border border-zinc-700 rounded-lg px-2 py-1 jb-body text-[11px] text-zinc-200 whitespace-nowrap"
          style={{ left: `${(x(activo) / W) * 100}%`, transform: `translateX(${activo > pts.length / 2 ? '-105%' : '5%'})` }}>
          <span className="text-zinc-400">{fechaCorta(sel.fecha)}</span> · <span className="font-semibold">{sel.v.toFixed(1)} kg</span>
        </div>
      )}
    </div>
  );
}

// Constancia de las últimas 4 semanas: cada día con ✓ si registró comida.
function CalendarioConstancia({ rows }) {
  const hoy = todayISO();
  const registrados = new Set((rows || [])
    .filter(r => Number(r.comidas_count) > 0 || Number(r.kcal_consumidas) > 0)
    .map(r => String(r.fecha).slice(0, 10)));
  const dow = new Date(hoy + 'T12:00:00').getDay();
  const lunesActual = addDaysISO(hoy, dow === 0 ? -6 : 1 - dow);
  const inicio = addDaysISO(lunesActual, -21);
  const dias = Array.from({ length: 28 }, (_, i) => addDaysISO(inicio, i));
  const pasados = dias.filter(d => d <= hoy);
  const hechos = pasados.filter(d => registrados.has(d)).length;

  return (
    <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
      <div className="flex items-center justify-between mb-3">
        <h3 className="jb-display text-sm text-zinc-200">TU CONSTANCIA · 4 SEMANAS</h3>
        <span className="jb-body text-xs text-zinc-400 tabular-nums"><span className="text-orange-400 font-semibold">{hechos}</span>/{pasados.length} días</span>
      </div>
      <div className="grid grid-cols-7 gap-1.5 mb-1">
        {['L', 'M', 'M', 'J', 'V', 'S', 'D'].map((l, i) => <span key={i} className="jb-body text-[10px] text-zinc-500 text-center">{l}</span>)}
      </div>
      <div className="grid grid-cols-7 gap-1.5">
        {dias.map(d => {
          const futuro = d > hoy;
          const hecho = registrados.has(d);
          const esHoy = d === hoy;
          return (
            <div key={d} title={fechaCorta(d)}
              className={`aspect-square rounded-lg flex items-center justify-center text-[11px] jb-body border ${futuro
                ? 'border-transparent bg-zinc-900/40 text-zinc-700'
                : hecho ? 'bg-orange-500 border-orange-500 text-zinc-950 font-bold' : 'bg-zinc-950 border-zinc-800 text-zinc-600'} ${esHoy ? 'ring-2 ring-orange-400 ring-offset-1 ring-offset-zinc-900' : ''}`}>
              {hecho && !futuro ? '✓' : Number(d.slice(8, 10))}
            </div>
          );
        })}
      </div>
    </div>
  );
}

function ProgressTab({ username, form, setForm, nombre, vistaInicial }) {
  const [vista, setVista] = useState(vistaInicial === 'fotos' ? 'fotos' : 'tendencias');
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [rango, setRango] = useState(30);

  useEffect(() => { load(); }, [username]);

  async function load() {
    setLoading(true);
    try {
      const { data } = await supabase.from('historial').select('*')
        .eq('username', username).order('fecha', { ascending: true }).limit(1500);
      setRows(data || []);
    } catch { setRows([]); }
    setLoading(false);
  }

  const filtrados = useMemo(() => {
    const limite = new Date();
    limite.setDate(limite.getDate() - rango);
    return rows.filter(r => {
      const d = new Date(String(r.fecha).slice(0, 10) + 'T00:00:00');
      return !isNaN(d) && d >= limite;
    });
  }, [rows, rango]);

  const stats = useMemo(() => {
    if (!filtrados.length) return null;
    const conComida = filtrados.filter(r => Number(r.kcal_consumidas) > 0);
    const promKcal = conComida.length ? conComida.reduce((a, r) => a + Number(r.kcal_consumidas), 0) / conComida.length : 0;
    const promProt = conComida.length ? conComida.reduce((a, r) => a + Number(r.proteina_g || 0), 0) / conComida.length : 0;
    const objetivos = conComida.filter(r => Number(r.kcal_objetivo) > 0);
    const promObj = objetivos.length ? objetivos.reduce((a, r) => a + Number(r.kcal_objetivo), 0) / objetivos.length : 0;
    // Adherencia: días dentro del ±15% de su objetivo
    const enRango = objetivos.filter(r => {
      const ratio = Number(r.kcal_consumidas) / Number(r.kcal_objetivo);
      return ratio >= 0.85 && ratio <= 1.15;
    }).length;
    const adherencia = objetivos.length ? (enRango / objetivos.length) * 100 : null;
    return { promKcal, promProt, promObj, adherencia, diasRegistrados: conComida.length, totalDias: filtrados.length, enRango, objetivos: objetivos.length };
  }, [filtrados]);

  const analisis = useMemo(() => {
    try {
      return filtrados.length ? analizarProgreso(filtrados, form || {}) : null;
    } catch (e) {
      console.error('Error al analizar el progreso:', e);
      return null;
    }
  }, [filtrados, form]);

  // Mismo criterio que usa el coach (analizarProgreso): en los campos de
  // composición corporal, descarta valores atípicos aislados (ej. un
  // registro viejo con el peso de fábrica) para que el gráfico cuente
  // la misma historia que el veredicto de arriba.
  const CAMPOS_CORPORALES = ['peso', 'grasa_pct', 'masa_muscular', 'masa_magra', 'imc'];
  const serie = (campo) => {
    let base = filtrados
      .filter(r => r[campo] !== null && r[campo] !== undefined && Number.isFinite(Number(r[campo])))
      .map(r => ({ v: Number(r[campo]), fecha: r.fecha }));
    if (CAMPOS_CORPORALES.includes(campo) && base.length >= 3) {
      const ordenados = base.map(p => p.v).slice().sort((a, b) => a - b);
      const mediana = ordenados.length % 2
        ? ordenados[(ordenados.length - 1) / 2]
        : (ordenados[ordenados.length / 2 - 1] + ordenados[ordenados.length / 2]) / 2;
      if (mediana > 0) base = base.filter(p => Math.abs(p.v - mediana) / mediana <= 0.15);
    }
    return base;
  };

  const subNav = (
    <div className="flex gap-2">
      <button onClick={() => setVista('tendencias')}
        className={`jb-display text-xs px-3 py-1.5 rounded-lg transition-colors ${vista === 'tendencias' ? 'bg-orange-500 text-zinc-950 font-semibold' : 'bg-zinc-900 text-zinc-400 border border-zinc-800'}`}>
        Tendencias
      </button>
      <button onClick={() => setVista('fotos')}
        className={`jb-display text-xs px-3 py-1.5 rounded-lg flex items-center gap-1.5 transition-colors ${vista === 'fotos' ? 'bg-orange-500 text-zinc-950 font-semibold' : 'bg-zinc-900 text-zinc-400 border border-zinc-800'}`}>
        <Camera size={13} /> Fotos
      </button>
    </div>
  );

  if (vista === 'fotos') {
    return (
      <div className="flex flex-col gap-6 min-w-0">
        {subNav}
        <PhotosTab username={username} pesoActual={form?.peso} />
      </div>
    );
  }

  if (loading) {
    return (
      <div className="flex flex-col gap-4 min-w-0">
        {subNav}
        <Skeleton className="h-10 w-full max-w-md rounded-xl" />
        <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-5 flex flex-col gap-3 min-w-0">
          <Skeleton className="h-4 w-48" />
          <div className="flex justify-around py-2">
            <Skeleton className="h-16 w-16 rounded-full" />
            <Skeleton className="h-16 w-16 rounded-full" />
            <Skeleton className="h-16 w-16 rounded-full" />
          </div>
        </div>
        <Skeleton className="h-32 w-full rounded-2xl" />
      </div>
    );
  }

  if (rows.length === 0) {
    return (
      <div className="flex flex-col gap-6 min-w-0">
        {subNav}
        {setForm && <MetaPesoCard form={form} setForm={setForm} />}
        <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-8 text-center">
          <TrendingUp className="text-zinc-700 mx-auto mb-3" size={40} />
          <h2 className="jb-display text-lg text-zinc-200 mb-2">TU PROGRESO EMPIEZA HOY</h2>
          <p className="jb-body text-sm text-zinc-500">
            Cada vez que registres tu peso o tus comidas, se guarda automáticamente.
            En unos días verás aquí tus tendencias y promedios.
          </p>
        </div>
      </div>
    );
  }

  const puntosPeso = serie('peso');
  const pesoActual = Number(form?.peso) || (puntosPeso.length ? puntosPeso[puntosPeso.length - 1].v : 0);
  const cambioPeso = puntosPeso.length >= 2 ? puntosPeso[puntosPeso.length - 1].v - puntosPeso[0].v : null;
  const pesoInicial = Number(form?.pesoInicial) || null;
  const pesoObjetivo = Number(form?.pesoObjetivo) || null;
  let avanceMeta = null;
  if (pesoInicial && pesoObjetivo && pesoInicial !== pesoObjetivo && pesoActual) {
    avanceMeta = Math.max(0, Math.min(100, ((pesoInicial - pesoActual) / (pesoInicial - pesoObjetivo)) * 100));
  }
  const etiquetaRango = rango === 7 ? '7 días' : rango === 30 ? '30 días' : rango === 90 ? '3 meses' : rango === 180 ? '6 meses' : '1 año';

  return (
    <div className="flex flex-col gap-5 min-w-0">
      {subNav}

      {/* Tablero: dónde estás hoy y cuánto avanzaste en el periodo */}
      <div className="relative bg-zinc-900 border border-orange-500/30 rounded-3xl p-5 overflow-hidden"
        style={{ boxShadow: '0 0 40px -12px rgba(232,89,12,.35)' }}>
        <div className="absolute -top-16 -right-16 w-48 h-48 rounded-full pointer-events-none"
          style={{ background: 'radial-gradient(circle, rgba(232,89,12,.18), transparent 70%)' }} />
        <p className="relative jb-body text-[11px] text-zinc-500 uppercase tracking-wider mb-1">Tu peso hoy</p>
        <div className="relative flex items-end gap-3 mb-3">
          <p className="jb-display text-5xl text-zinc-50 leading-none tabular-nums">{pesoActual ? Number(pesoActual).toFixed(1) : '—'}<span className="text-lg text-zinc-400 ml-1">kg</span></p>
          {cambioPeso !== null && Math.abs(cambioPeso) >= 0.05 && (
            <p className="jb-body text-sm pb-1 tabular-nums">
              <span className="text-orange-400 font-semibold">{cambioPeso > 0 ? '+' : '−'}{Math.abs(cambioPeso).toFixed(1)} kg</span>
              <span className="text-zinc-500"> en {etiquetaRango}</span>
            </p>
          )}
        </div>
        {avanceMeta !== null && (
          <div className="relative mb-4">
            <div className="flex justify-between jb-body text-[11px] text-zinc-400 mb-1 tabular-nums">
              <span>Meta: {pesoObjetivo} kg</span>
              <span className="text-orange-400 font-semibold">{Math.round(avanceMeta)}%</span>
            </div>
            <div className="h-2 rounded-full bg-zinc-800 overflow-hidden">
              <div className="h-full rounded-full bg-orange-500" style={{ width: `${avanceMeta}%`, transition: 'width .7s ease' }} />
            </div>
            <p className="jb-body text-[11px] text-zinc-500 mt-1">
              {avanceMeta >= 100 ? '¡Llegaste a tu meta!' : `Te faltan ${Math.abs(pesoActual - pesoObjetivo).toFixed(1)} kg`}
            </p>
          </div>
        )}
        {stats && (
          <div className="relative grid grid-cols-3 gap-2">
            {[
              [`${stats.diasRegistrados}`, `días registrados de ${stats.totalDias}`],
              [stats.adherencia !== null ? `${Math.round(stats.adherencia)}%` : '—', 'días en tu objetivo'],
              [Math.round(stats.promKcal) || '—', 'kcal por día'],
            ].map(([valor, texto]) => (
              <div key={texto} className="bg-zinc-950/70 border border-zinc-800 rounded-xl px-2 py-2.5 text-center">
                <p className="jb-display text-xl text-orange-500 tabular-nums leading-none">{valor}</p>
                <p className="jb-body text-[10px] text-zinc-400 leading-tight mt-1">{texto}</p>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="flex gap-2 overflow-x-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
        {[7, 30, 90, 180, 365].map(d => (
          <button key={d} onClick={() => setRango(d)}
            className={`jb-body text-xs px-3 py-1.5 rounded-full shrink-0 transition-colors ${rango === d ? 'bg-orange-500 text-zinc-950 font-semibold' : 'bg-zinc-900 text-zinc-400 border border-zinc-800'}`}>
            {d === 7 ? '7 días' : d === 30 ? '30 días' : d === 90 ? '3 meses' : d === 180 ? '6 meses' : '1 año'}
          </button>
        ))}
      </div>

      <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        <div className="flex items-center justify-between mb-2">
          <h3 className="jb-display text-sm text-zinc-200">TU PESO</h3>
          <span className="jb-body text-[11px] text-zinc-500">Toca el gráfico para ver cada día</span>
        </div>
        <GraficoPeso puntos={puntosPeso} meta={pesoObjetivo} />
      </div>

      <CalendarioConstancia rows={rows} />

      {analisis && <CoachCard analisis={analisis} />}

      <BotonCompartir username={username} nombre={nombre} rows={rows} stats={stats} />

      <div className="grid sm:grid-cols-3 gap-3">
        {[
          ['grasa_pct', '% GRASA CORPORAL', '%'],
          ['masa_muscular', 'MASA MUSCULAR', ' kg'],
          ['kcal_consumidas', 'CALORÍAS DIARIAS', ''],
        ].map(([campo, titulo, sufijo]) => {
          const pts = serie(campo);
          return (
            <div key={campo} className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
              <h3 className="jb-display text-xs text-zinc-400 mb-2">{titulo}</h3>
              {pts.length < 2 ? (
                <p className="jb-body text-xs text-zinc-600 py-6 text-center">Necesitas al menos 2 días de registro.</p>
              ) : (
                <MiniChart points={pts} color="#E8590C" suffix={sufijo} />
              )}
            </div>
          );
        })}
      </div>

      {setForm && <MetaPesoCard form={form} setForm={setForm} />}

      <p className="jb-body text-xs text-zinc-600 text-center">
        Tu historial se guarda solo cada vez que usas la app. Mientras más registres, más claro verás tu avance.
      </p>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* GUÍA DE PRIMEROS PASOS                                              */
/* ------------------------------------------------------------------ */

function AyudaTab({ texto, id }) {
  const key = id ? `jb_ayuda_no_${id}` : null;
  const [cerrado, setCerrado] = useState(() => {
    if (!key) return false;
    try { return localStorage.getItem(key) === '1'; } catch { return false; }
  });
  if (cerrado) return null;
  function cerrar() {
    setCerrado(true);
    if (key) { try { localStorage.setItem(key, '1'); } catch {} }
  }
  return (
    <div className="bg-zinc-900/60 border border-zinc-800 rounded-xl p-3 flex items-center gap-2.5 mb-4">
      <span className="w-6 h-6 rounded-full bg-orange-500/15 border border-orange-500/30 flex items-center justify-center text-xs shrink-0">💡</span>
      <p className="jb-body text-xs text-zinc-400 flex-1">{texto}</p>
      {key && (
        <button onClick={cerrar} className="text-zinc-600 hover:text-zinc-400 shrink-0 p-1"><X size={14} /></button>
      )}
    </div>
  );
}

function BienvenidaModal({ nombre, username, telefonoActual, onClose }) {
  const [paso, setPaso] = useState(0);
  const [telefono, setTelefono] = useState('');
  const [nombreInput, setNombreInput] = useState('');
  const [guardandoTel, setGuardandoTel] = useState(false);
  const [guardandoNombre, setGuardandoNombre] = useState(false);
  const [errNombre, setErrNombre] = useState('');
  const [errTelefono, setErrTelefono] = useState('');
  const [estadoPush, setEstadoPush] = useState('cargando'); // cargando | yaActivo | disponible | bloqueado | nosoportado | iosNoInstalado
  const [incluirPasoNotif, setIncluirPasoNotif] = useState(null); // se fija una sola vez al cargar, para que el paso no aparezca/desaparezca a mitad de recorrido
  const [activandoPush, setActivandoPush] = useState(false);
  const nombreMostrar = nombre || nombreInput;

  // Mismo chequeo que RecordatorioBanner, pero acá decide si el paso de
  // notificaciones entra al recorrido del onboarding o no — si ya las
  // tiene activas, no tiene sentido volver a pedírselas. Una vez que
  // incluirPasoNotif queda fijado, ya no cambia en este recorrido —
  // aunque el alumno las active a mitad de camino, el paso sigue
  // existiendo hasta que él mismo avance, para que los índices de los
  // demás pasos no se corran de golpe.
  useEffect(() => {
    (async () => {
      const ua = window.navigator.userAgent || '';
      const esIOS = /iPad|iPhone|iPod/.test(ua) && !window.MSStream;
      const instalada = window.matchMedia('(display-mode: standalone)').matches
        || window.navigator.standalone === true;
      if (!('Notification' in window) || !('serviceWorker' in navigator) || !('PushManager' in window)) {
        const e = esIOS && !instalada ? 'iosNoInstalado' : 'nosoportado';
        setEstadoPush(e); setIncluirPasoNotif(true);
        return;
      }
      if (Notification.permission === 'denied') { setEstadoPush('bloqueado'); setIncluirPasoNotif(true); return; }
      if (Notification.permission === 'granted') {
        try {
          const reg = await navigator.serviceWorker.ready;
          const sub = await reg.pushManager.getSubscription();
          setEstadoPush(sub ? 'yaActivo' : 'disponible');
          setIncluirPasoNotif(!sub);
        } catch { setEstadoPush('disponible'); setIncluirPasoNotif(true); }
        return;
      }
      setEstadoPush('disponible'); setIncluirPasoNotif(true);
    })();
  }, []);

  async function activarPush() {
    setActivandoPush(true);
    try {
      const permiso = await Notification.requestPermission();
      if (permiso !== 'granted') {
        setEstadoPush(permiso === 'denied' ? 'bloqueado' : 'disponible');
        setActivandoPush(false);
        return;
      }
      const reg = await navigator.serviceWorker.ready;
      let sub = await reg.pushManager.getSubscription();
      if (!sub) {
        sub = await reg.pushManager.subscribe({
          userVisibleOnly: true,
          applicationServerKey: base64ToUint8(VAPID_PUBLIC),
        });
      }
      const j = sub.toJSON();
      await supabase.from('push_subs').upsert({
        username, endpoint: j.endpoint, p256dh: j.keys.p256dh, auth: j.keys.auth, activa: true,
      }, { onConflict: 'endpoint' });
      setEstadoPush('yaActivo');
      // Recién acá existe una suscripción real a la que mandarle algo —
      // este es el momento más cercano posible a "el instante en que
      // se registra" en el que Jonah puede saludarlo de verdad.
      // El servidor solo saluda al dueño de la sesión, así que va el token.
      const { data: { session } } = await supabase.auth.getSession();
      fetch('/api/bienvenida-push', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${session?.access_token || ''}` },
        body: JSON.stringify({ username }),
      }).catch(() => { /* si falla el saludo, no bloquea el onboarding */ });
    } catch (e) { /* si falla, no bloquea el avance del onboarding */ }
    setActivandoPush(false);
  }

  const pasos = [
    ...(nombre ? [] : [{
      emoji: '😄', titulo: '¿CÓMO TE LLAMAS?',
      texto: 'Así puedo saludarte como se debe y acompañarte de forma más personal.',
      esNombre: true,
    }]),
    ...(telefonoActual ? [] : [{
      emoji: '📱', titulo: '¿QUIERES QUE TE ACOMPAÑE DE CERCA?',
      texto: 'Déjame tu WhatsApp y te aviso antes de que pierdas tu racha, te doy ánimo cuando lo necesites y te aviso a tiempo si tu prueba está por vencer. Nada de spam, solo lo importante.',
      esTelefono: true,
    }]),
    ...(incluirPasoNotif ? [{
      emoji: '🦍', titulo: 'ACTIVA TUS NOTIFICACIONES',
      texto: 'Es lo más importante que puedes activar: así Jonah te avisa si se te pasa una comida, te acompaña cuando lo necesites, y te avisa a tiempo antes de que venza tu plan — para que nunca pierdas tu progreso por no enterarte.',
      esNotificacion: true,
    }] : []),
    // Antes eran 7 pantallas de explicación; ahora son 2, para que el
    // alumno llegue rápido a usar la app.
    {
      emoji: '👋', titulo: `¡BIENVENIDO${nombreMostrar ? ', ' + nombreMostrar.split(' ')[0].toUpperCase() : ''}!`,
      texto: 'Te ayudo a saber cuánto y qué comer para llegar a tu objetivo, con comida peruana y sin pesar nada. Así funciona:',
      extra: [
        ['1 · Tus datos', 'Edad, estatura y peso. Sin cinta métrica'],
        ['2 · Tu objetivo', 'Perder grasa, ganar músculo o mantener'],
        ['3 · Tus comidas', '"1 taza de arroz", "2 huevos"… y listo'],
      ],
    },
    {
      emoji: '📅', titulo: 'TU RUTINA ES SIMPLE',
      texto: 'Solo registra lo que comes cada día. Tus datos quedan guardados.',
      extra: [
        ['Todos los días', 'Registra lo que comes'],
        ['Si no sabes qué comer', 'Toca «¿Qué puedo comer?»'],
        ['Cada domingo', 'Pésate en ayunas y anótalo'],
        ['Cada 2 semanas', 'Mídete y toma tus fotos'],
      ],
    },
  ];
  const p = pasos[paso];
  const ultimo = paso === pasos.length - 1;

  async function guardarTelefono() {
    const limpio = telefono.replace(/\D/g, '');
    if (limpio.length < 9) { setErrTelefono('Escribe tu número de WhatsApp (9 dígitos) para que Jonah pueda acompañarte.'); return false; }
    setErrTelefono('');
    setGuardandoTel(true);
    try {
      await supabase.from('alumnos').update({ telefono: limpio }).eq('username', username);
    } catch (e) { /* si falla, no bloquea el avance del onboarding */ }
    setGuardandoTel(false);
    return true;
  }

  async function guardarNombre() {
    if (!nombreInput.trim()) { setErrNombre('Escribe tu nombre para continuar.'); return false; }
    setErrNombre('');
    setGuardandoNombre(true);
    try {
      await supabase.from('alumnos').update({ nombre: nombreInput.trim() }).eq('username', username);
    } catch (e) { /* si falla, no bloquea el avance del onboarding */ }
    setGuardandoNombre(false);
    return true;
  }

  async function avanzar() {
    if (p.esNombre) { const ok = await guardarNombre(); if (!ok) return; }
    if (p.esTelefono) { const ok = await guardarTelefono(); if (!ok) return; }
    // El botón principal en el paso de notificaciones ES la acción de
    // activarlas — dispara el permiso del navegador. Se avanza igual
    // después, acepte o no: bloquearlo indefinidamente si dice que no
    // sería peor experiencia que solo insistir una vez con fuerza.
    if (p.esNotificacion && estadoPush === 'disponible') await activarPush();
    if (ultimo) onClose(); else setPaso(paso + 1);
  }

  return (
    <div className="fixed inset-0 bg-black/80 flex items-center justify-center p-4 z-50">
      <div className="bg-zinc-900 border border-orange-500/40 rounded-2xl max-w-md w-full p-6">
        <div className="text-center mb-5">
          <div className="w-16 h-16 rounded-full bg-orange-500/15 border border-orange-500/30 flex items-center justify-center text-4xl mx-auto mb-3">
            {p.esTelefono ? <Phone className="text-orange-500" size={26} /> : p.emoji}
          </div>
          <h2 className="jb-display text-xl text-zinc-50 mb-3">{p.titulo}</h2>
          <p className="jb-body text-sm text-zinc-300 leading-relaxed">{p.texto}</p>
          {p.esNombre && (
            <div className="mt-4 text-left">
              <input value={nombreInput} onChange={e => setNombreInput(e.target.value)}
                className={inputCls} placeholder="Ej. María Pérez" autoFocus />
              {errNombre && <p className="text-red-400 text-xs jb-body mt-1.5 flex items-center gap-1.5"><AlertTriangle size={12} />{errNombre}</p>}
            </div>
          )}
          {p.esTelefono && (
            <div className="mt-4 text-left">
              <input type="tel" inputMode="tel" value={telefono} onChange={e => setTelefono(e.target.value)}
                className={inputCls} placeholder="999 888 777" autoFocus />
              {errTelefono
                ? <p className="text-red-400 text-xs jb-body mt-1.5 flex items-center gap-1.5"><AlertTriangle size={12} />{errTelefono}</p>
                : <p className="jb-body text-[11px] text-zinc-600 mt-1.5">Así puedo escribirte directo cuando te haga falta un empujón — nada de spam, solo acompañamiento 🔥</p>}
            </div>
          )}
          {p.esNotificacion && (
            <div className="mt-4 text-left">
              {estadoPush === 'bloqueado' && (
                <p className="jb-body text-xs text-red-400 bg-red-950/30 border border-red-800/40 rounded-lg p-2.5">
                  Parece que ya las bloqueaste antes. Puedes activarlas manualmente en los ajustes de notificaciones de tu navegador para este sitio, y luego seguir aquí.
                </p>
              )}
              {estadoPush === 'nosoportado' && (
                <p className="jb-body text-xs text-zinc-500 bg-zinc-950 border border-zinc-800 rounded-lg p-2.5">
                  Tu navegador actual no soporta notificaciones. Puedes seguir usando la app normal, solo no vas a recibir avisos.
                </p>
              )}
              {estadoPush === 'iosNoInstalado' && (
                <div className="jb-body text-xs text-orange-400 bg-orange-950/20 border border-orange-800/40 rounded-lg p-2.5">
                  En iPhone, primero instala la app en tu pantalla de inicio para poder recibir notificaciones. Toma 1 minuto.
                  <BotonGuiaIphone />
                </div>
              )}
            </div>
          )}
          {p.extra && (
            <div className="mt-4 flex flex-col gap-2">
              {p.extra.map(([cuando, que]) => (
                <div key={cuando} className="bg-zinc-950 border border-zinc-800 rounded-lg p-2.5 flex items-center gap-3 text-left">
                  <span className="jb-display text-[11px] text-orange-500 w-24 shrink-0">{cuando.toUpperCase()}</span>
                  <span className="jb-body text-xs text-zinc-300">{que}</span>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="flex justify-center gap-1.5 mb-5">
          {pasos.map((_, i) => (
            <div key={i} className={`h-1.5 rounded-full transition-all ${i === paso ? 'w-6 bg-orange-500' : 'w-1.5 bg-zinc-700'}`} />
          ))}
        </div>

        <div className="flex gap-2">
          {paso > 0 && (
            <button onClick={() => setPaso(paso - 1)} className={btnGhost + ' py-2.5 px-4'}>Atrás</button>
          )}
          <button onClick={avanzar} disabled={guardandoTel || guardandoNombre || activandoPush} className={btnPrimary + ' flex-1 py-2.5'}>
            {(guardandoTel || guardandoNombre || activandoPush) ? <Loader2 className="animate-spin" size={18} /> : (
              ultimo ? '¡Empecemos!'
              : (p.esNombre || p.esTelefono) ? 'Guardar y seguir'
              : (p.esNotificacion && estadoPush === 'disponible') ? 'Activar notificaciones'
              : (p.esNotificacion) ? 'Continuar'
              : 'Siguiente'
            )}
          </button>
        </div>

        {!ultimo && !p.esNombre && !p.esNotificacion && !p.esTelefono && (
          <button onClick={onClose} className="jb-body text-sm text-zinc-400 hover:text-zinc-200 underline underline-offset-2 mt-3 w-full text-center">
            Saltar y empezar
          </button>
        )}
      </div>
    </div>
  );
}

function PrimerosPasos({ form, mealPlan, tieneFotos, onIr, onVerGuia }) {
  const [oculto, setOculto] = useState(false);

  const midio = tieneDatosBasicos(form);
  const eligioObjetivo = !!form.objetivo;
  const registroComida = Object.values(mealPlan.meals || {}).some(e => e.some(x => x.foodKey));

  // Primero la comida: es lo más fácil y donde se ve la magia de la app.
  // Los datos y el objetivo vienen después, para ajustar la meta.
  const pasos = [
    { id: 'meal', hecho: registroComida, titulo: 'Registra tu primera comida', texto: 'Tómale foto a tu plato — la IA la reconoce al toque', tab: 'registrar' },
    { id: 'calc', hecho: midio, titulo: 'Ajusta tu meta a tu cuerpo', texto: 'Edad, estatura y peso · 30 segundos, sin cinta métrica', tab: 'calc' },
    { id: 'goal', hecho: eligioObjetivo, titulo: 'Elige tu objetivo', texto: 'Perder grasa, ganar músculo o mantener', tab: 'goal' },
    { id: 'photo', hecho: tieneFotos, titulo: 'Toma tus fotos de inicio', texto: 'Tu punto de partida para comparar después', tab: 'photos' },
  ];

  const completados = pasos.filter(p => p.hecho).length;
  const todoListo = completados === pasos.length;

  if (todoListo || oculto) {
    return (
      <button onClick={onVerGuia}
        className="jb-body text-xs text-zinc-500 hover:text-orange-500 flex items-center gap-1.5 mb-4">
        <AlertTriangle size={13} /> ¿Cómo funciona la app?
      </button>
    );
  }

  const siguiente = pasos.find(p => !p.hecho);

  return (
    <div className="bg-zinc-900 border border-orange-500/40 rounded-2xl p-5 mb-6">
      <div className="flex items-center justify-between mb-1">
        <h2 className="jb-display text-base text-zinc-200">🚀 PRIMEROS PASOS</h2>
        <span className="jb-body text-xs text-zinc-500">{completados} de {pasos.length}</span>
      </div>
      <p className="jb-body text-xs text-zinc-500 mb-3">
        Empieza por lo más fácil: registra lo que comiste hoy. Luego ajustamos tu meta a tu cuerpo.
      </p>

      <div className="w-full h-1.5 bg-zinc-800 rounded-full overflow-hidden mb-4">
        <div className="h-full bg-orange-500 rounded-full transition-all"
          style={{ width: `${(completados / pasos.length) * 100}%` }} />
      </div>

      <div className="flex flex-col gap-2 mb-4">
        {pasos.map((p, i) => (
          <button key={p.id} onClick={() => onIr(p.tab)}
            className={`flex items-center gap-3 rounded-xl p-3 text-left transition-colors border ${p.hecho
              ? 'bg-emerald-950/20 border-emerald-800/40'
              : p.id === siguiente?.id
                ? 'bg-zinc-950 border-orange-500/50 hover:border-orange-500'
                : 'bg-zinc-950 border-zinc-800 hover:border-zinc-700'}`}>
            <div className={`w-7 h-7 rounded-full flex items-center justify-center shrink-0 jb-display text-xs transition-all duration-300 ${p.hecho
              ? 'bg-emerald-500 text-zinc-950 scale-110' : 'bg-zinc-800 text-zinc-400'}`}>
              {p.hecho ? <span className="animate-bounce">✓</span> : i + 1}
            </div>
            <div className="flex-1 min-w-0">
              <div className={`jb-body text-sm ${p.hecho ? 'text-zinc-500 line-through' : 'text-zinc-100'}`}>
                {p.titulo}
              </div>
              {!p.hecho && <div className="jb-body text-xs text-zinc-600">{p.texto}</div>}
            </div>
            {!p.hecho && <ChevronRight size={16} className="text-zinc-600 shrink-0" />}
          </button>
        ))}
      </div>

      <div className="flex gap-2">
        {siguiente && (
          <button onClick={() => onIr(siguiente.tab)} className={btnPrimary + ' flex-1 py-2.5 text-sm'}>
            Continuar: {siguiente.titulo}
          </button>
        )}
        <button onClick={onVerGuia} className={btnGhost + ' py-2.5 px-4 text-sm'}>Ver guía</button>
      </div>

      <button onClick={() => setOculto(true)}
        className="jb-body text-[11px] text-zinc-600 hover:text-zinc-400 mt-3 w-full text-center">
        Ocultar por ahora
      </button>
    </div>
  );
}

/* Confeti simple con CSS puro — sin librerías externas */
function Confetti() {
  const colores = ['#f97316', '#34d399', '#a78bfa', '#fbbf24'];
  const piezas = Array.from({ length: 40 }, (_, i) => ({
    id: i,
    left: Math.random() * 100,
    delay: Math.random() * 0.4,
    duracion: 1.6 + Math.random() * 1,
    color: colores[i % colores.length],
    rotar: Math.random() * 360,
  }));
  return (
    <div className="fixed inset-0 pointer-events-none z-[60] overflow-hidden">
      {piezas.map(p => (
        <div key={p.id} style={{
          position: 'absolute', left: `${p.left}%`, top: '-5%',
          width: 8, height: 14, background: p.color,
          animation: `jb-confetti ${p.duracion}s ease-in ${p.delay}s forwards`,
          transform: `rotate(${p.rotar}deg)`,
        }} />
      ))}
      <style>{`@keyframes jb-confetti { to { transform: translateY(115vh) rotate(600deg); opacity: 0.3; } }`}</style>
    </div>
  );
}

/* "Beast Score": puntuación lúdica del día, combina qué tan cerca estás
   de tu objetivo de kcal con tu racha actual. No reemplaza los anillos
   reales de macros — es un plus divertido encima de ellos. */
/* Mini-juego "Adivina las calorías": muestra un alimento peruano al
   azar y el alumno adivina cuántas kcal tiene por 100g antes de
   revelar la respuesta — engancha la curiosidad y educa sin sentirse
   como una tarea más. */
function BeastScoreCard({ totalsHoy, targets, username }) {
  const [racha, setRacha] = useState(0);
  const [celebrado, setCelebrado] = useState(false);
  const [mostrarConfeti, setMostrarConfeti] = useState(false);
  const [subioNivel, setSubioNivel] = useState(false);
  const nivelAnteriorRef = useRef(null);

  useEffect(() => {
    if (!username) return;
    (async () => {
      try {
        const desde = addDaysISO(todayISO(), -60);
        const { data } = await supabase.from('historial')
          .select('fecha, comidas_count').eq('username', username).gte('fecha', desde)
          .order('fecha', { ascending: false });
        const m = {};
        (data || []).forEach(r => { m[r.fecha] = Number(r.comidas_count) || 0; });
        const hoy = todayISO();
        const registro = (iso) => (m[iso] || 0) > 0;
        let r = 0;
        let cursor = registro(hoy) ? hoy : addDaysISO(hoy, -1);
        while (registro(cursor)) { r++; cursor = addDaysISO(cursor, -1); }
        setRacha(r);
      } catch {}
    })();
  }, [username]);

  const objetivoKcal = targets ? targets.kcal : 0;
  const ratio = objetivoKcal ? Math.min(1.15, totalsHoy.kcal / objetivoKcal) : 0;
  // Puntaje: qué tan cerca del 100% (sin pasarse mucho) + bono por racha, tope 100
  const cercania = objetivoKcal ? Math.max(0, 100 - Math.abs(100 - ratio * 100) * 2) : 0;
  const bonoRacha = Math.min(15, racha * 2);
  const score = Math.round(Math.min(100, cercania * 0.85 + bonoRacha));

  const dentroDeRango = objetivoKcal && ratio >= 0.85 && ratio <= 1.15;

  const nivel = score >= 90 ? { txt: '¡Modo bestia total!', emoji: '🦍', key: 'bestia' }
    : score >= 70 ? { txt: 'Vas con todo hoy', emoji: '🔥', key: 'fuego' }
    : score >= 40 ? { txt: 'Aún puedes con más', emoji: '💪', key: 'medio' }
    : { txt: 'El día recién empieza', emoji: '🌱', key: 'inicio' };

  // Animación al subir de nivel (no en la primera carga)
  useEffect(() => {
    if (nivelAnteriorRef.current !== null && nivelAnteriorRef.current !== nivel.key) {
      const orden = ['inicio', 'medio', 'fuego', 'bestia'];
      if (orden.indexOf(nivel.key) > orden.indexOf(nivelAnteriorRef.current)) {
        setSubioNivel(true);
        vibrar([20, 40, 20]);
        reproducirSonido('logro');
        showToast(`${nivel.emoji} ¡Subiste a "${nivel.txt}"!`);
        const t = setTimeout(() => setSubioNivel(false), 1200);
        return () => clearTimeout(t);
      }
    }
    nivelAnteriorRef.current = nivel.key;
  }, [nivel.key]);

  const [jonahCelebra, setJonahCelebra] = useState(false);

  useEffect(() => {
    if (dentroDeRango && !celebrado && totalsHoy.kcal > 0) {
      setCelebrado(true);
      setMostrarConfeti(true);
      setJonahCelebra(true);
      vibrar([20, 40, 20, 40, 20]);
      reproducirSonido('logro');
      showToast('🔥 ¡Completaste tu objetivo de hoy!');
      const t = setTimeout(() => setMostrarConfeti(false), 2600);
      const t2 = setTimeout(() => setJonahCelebra(false), 3400);
      return () => { clearTimeout(t); clearTimeout(t2); };
    }
  }, [dentroDeRango, celebrado, totalsHoy.kcal]);

  return (
    <div className={`relative bg-zinc-900 border border-zinc-800 rounded-2xl p-4 flex items-center gap-4 transition-transform duration-300 overflow-hidden ${subioNivel ? 'scale-[1.03]' : ''}`}>
      {mostrarConfeti && <Confetti />}
      {jonahCelebra && (
        <div className="absolute inset-0 z-30 bg-zinc-950 rounded-2xl flex items-center gap-3 px-4">
          <style>{`@keyframes jb-jonah-celebra { 0%, 100% { transform: scale(1) rotate(0deg); } 50% { transform: scale(1.2) rotate(-6deg); } }`}</style>
          <span className="text-4xl shrink-0" style={{ animation: 'jb-jonah-celebra 0.4s ease-in-out 3' }}>🦍</span>
          <p className="jb-display text-sm text-orange-400">¡Lo lograste! Modo bestia total 🔥</p>
        </div>
      )}
      {subioNivel && (
        <>
          <style>{`
            @keyframes jb-bolt-strike { 0% { opacity: 0; transform: translate(-50%, -60%); } 25% { opacity: 1; transform: translate(-50%, 20%); } 55% { opacity: 0; transform: translate(-50%, 80%); } 100% { opacity: 0; } }
            @keyframes jb-flash-once { 0% { opacity: 0; } 26% { opacity: 0.9; } 42% { opacity: 0; } 100% { opacity: 0; } }
          `}</style>
          <div className="absolute z-20 pointer-events-none" style={{ top: '-30%', left: '30%', width: 20, animation: 'jb-bolt-strike 1.1s ease-in forwards' }}>
            <svg width="20" height="140" viewBox="0 0 20 140" fill="none" style={{ filter: 'drop-shadow(0 0 6px #fff) drop-shadow(0 0 14px #f97316)' }}>
              <path d="M12 0 3 70h7l-4 70 15-80h-7L16 0z" fill="#fde68a" />
            </svg>
          </div>
          <div className="absolute inset-0 bg-white z-10 pointer-events-none" style={{ animation: 'jb-flash-once 1.1s ease-out forwards' }} />
        </>
      )}
      <div className="relative w-16 h-16 shrink-0">
        <svg width={64} height={64} style={{ transform: 'rotate(-90deg)' }}>
          <circle cx={32} cy={32} r={27} stroke="#27272a" strokeWidth={7} fill="none" />
          <circle cx={32} cy={32} r={27} stroke="#f97316" strokeWidth={7} fill="none"
            strokeDasharray={2 * Math.PI * 27} strokeDashoffset={2 * Math.PI * 27 * (1 - score / 100)}
            strokeLinecap="round" style={{ transition: 'stroke-dashoffset 0.6s ease' }} />
        </svg>
        <div className="absolute inset-0 flex items-center justify-center jb-display text-sm text-zinc-50">{score}</div>
      </div>
      <div className="flex-1">
        <p className="jb-display text-sm text-zinc-100">{nivel.emoji} ¿CÓMO VAS HOY? {score}%</p>
        <p className="jb-body text-xs text-zinc-500">
          {totalsHoy.kcal === 0 && racha > 0
            ? `Aún no registras hoy — tu racha ya te dio ${bonoRacha} pts. Registra algo y sube.`
            : `${nivel.txt}${racha > 0 ? ` · racha de ${racha} día(s)` : ''}`}
        </p>
      </div>
    </div>
  );
}

function saludoPorHora(d = new Date()) {
  const h = d.getHours();
  if (h >= 5 && h < 12) return 'Buenos días';
  if (h >= 12 && h < 19) return 'Buenas tardes';
  return 'Buenas noches';
}

// Inicio: saludo, anillo del día (el mismo de Comidas), botón para
// registrar la comida que toca y la línea del día con las 5 comidas.
