function StudentDashboard({ username, form, setForm, mealPlan, setMealPlan, onLogout, estadoGuardado, userRecord }) {
  const [tab, setTab] = useState('dash');
  const [registrarAl, setRegistrarAl] = useState(null); // { meal, id }: comida a registrar al llegar a Comidas
  const formRef = useRef(form);
  formRef.current = form;
  function irARegistrar(meal) {
    setRegistrarAl({ meal, id: Date.now() });
    setTab('meal');
    window.scrollTo({ top: 0 });
  }

  // Si la app se abrió desde un aviso ("No olvides registrar tu almuerzo"),
  // va directo al registro de esa comida. También si ya estaba abierta y
  // el aviso llega por el service worker.
  // "?ir=planes" (avisos de fin de prueba o de renovación) abre Planes.
  // "?ir=meta" (aviso de ajustar la meta) abre sus datos o su objetivo.
  function irAPlanesSiPide(url) {
    try {
      const ir = new URL(url, window.location.origin).searchParams.get('ir');
      if (ir === 'planes') {
        setRegistrarAl(null); setTab('planes'); window.scrollTo({ top: 0 });
        return true;
      }
      if (ir === 'meta') {
        setRegistrarAl(null); setTab(tieneDatosBasicos(formRef.current) ? 'goal' : 'calc'); window.scrollTo({ top: 0 });
        return true;
      }
    } catch {}
    return false;
  }
  useEffect(() => {
    const deUrl = leerRegistrarDeUrl(window.location.href);
    if (deUrl) irARegistrar(deUrl);
    else irAPlanesSiPide(window.location.href);
    try {
      const u = new URL(window.location.href);
      if (u.searchParams.has('registrar') || u.searchParams.has('ir')) {
        u.searchParams.delete('registrar'); u.searchParams.delete('ir');
        window.history.replaceState(null, '', u.pathname + u.search + u.hash);
      }
    } catch {}
    if (!('serviceWorker' in navigator)) return undefined;
    const alMensaje = (e) => {
      if (e.data?.tipo !== 'abrir-url') return;
      const meal = leerRegistrarDeUrl(e.data.url || '/');
      if (meal) irARegistrar(meal);
      else irAPlanesSiPide(e.data.url || '/');
    };
    navigator.serviceWorker.addEventListener('message', alMensaje);
    return () => navigator.serviceWorker.removeEventListener('message', alMensaje);
  }, []);
  // Fecha en que el alumno anotó su peso o sus medidas con cinta. La base
  // guarda cada día una copia del peso aunque no se haya vuelto a pesar, así
  // que esta fecha es la que dice cuándo se pesó o midió de verdad (la usan
  // el pesaje del domingo y el control quincenal).
  const pesoAntes = useRef(form.peso);
  const medidasAntes = useRef([form.cuello, form.cintura, form.cadera].join('|'));
  useEffect(() => {
    if (String(form.peso ?? '') === String(pesoAntes.current ?? '')) return;
    pesoAntes.current = form.peso;
    if (Number(form.peso) > 0 && form.pesoFecha !== todayISO()) setForm(v => ({ ...v, pesoFecha: todayISO() }));
  }, [form.peso]);
  useEffect(() => {
    const ahora = [form.cuello, form.cintura, form.cadera].join('|');
    if (ahora === medidasAntes.current) return;
    medidasAntes.current = ahora;
    if (form.medidasFecha !== todayISO()) setForm(v => ({ ...v, medidasFecha: todayISO() }));
  }, [form.cuello, form.cintura, form.cadera]);

  const [verGuia, setVerGuia] = useState(false);
  const [tieneFotos, setTieneFotos] = useState(false);
  const [recordatorioElegible, setRecordatorioElegible] = useState(null); // null = aún no se sabe
  const [instalarElegible, setInstalarElegible] = useState(null);
  const [ofrecerNotif, setOfrecerNotif] = useState(false);
  const [ajustarMeta, setAjustarMeta] = useState(false);

  // Anota en su ficha si le llegan los avisos (o por qué no), una vez al
  // abrir la app, para que Jonah lo vea en su panel.
  useEffect(() => {
    estadoPushEquipo().then(anotarEstadoAvisos).catch(() => {});
  }, [username]);
  const metaEstimada = !tieneDatosBasicos(form) || !form.objetivo;

  // Cuando el alumno pasa de 0 a 1 alimento registrado en el día, se le
  // ofrecen los recordatorios (una sola vez por equipo, y solo si el
  // navegador todavía puede pedirlos).
  const alimentosHoy = Object.values(mealPlan?.meals || {}).reduce((n, e) => n + e.filter(x => x.foodKey).length, 0);
  const alimentosAntes = useRef(alimentosHoy);
  useEffect(() => {
    const antes = alimentosAntes.current;
    alimentosAntes.current = alimentosHoy;
    if (!(antes === 0 && alimentosHoy > 0)) return;
    // Sin datos u objetivo: primero se le ofrece ajustar su meta (una vez
    // al día); los recordatorios se le ofrecen otro día.
    if (metaEstimada) {
      const marcaMeta = 'jb_ajusta_meta_' + username + '_' + todayISO();
      try { if (!localStorage.getItem(marcaMeta)) { localStorage.setItem(marcaMeta, '1'); setAjustarMeta(true); return; } } catch {}
    }
    const marca = 'jb_notif_tras_comida_' + username;
    try { if (localStorage.getItem(marca)) return; } catch { return; }
    estadoPushEquipo().then(estado => {
      if (estado !== 'disponible') return;
      try { localStorage.setItem(marca, '1'); } catch {}
      setOfrecerNotif(true);
    });
  }, [alimentosHoy, username]);

  // Primera comida en 1 toque (ver PrimeraComidaModal): solo para quien
  // nunca registró una comida y ya tiene su meta lista. "Ahora no" la
  // guarda hasta el día siguiente.
  const [nuncaRegistro, setNuncaRegistro] = useState(false);
  const [primeraDescartada, setPrimeraDescartada] = useState(() => {
    try { return localStorage.getItem('jb_primera_comida_no_' + username) === todayISO(); } catch { return false; }
  });
  useEffect(() => {
    let vivo = true;
    supabase.from('historial').select('fecha').eq('username', username).gt('comidas_count', 0).limit(1)
      .then(({ data, error }) => { if (vivo && !error) setNuncaRegistro((data || []).length === 0); })
      .then(null, () => {});
    return () => { vivo = false; };
  }, [username]);
  function registrarPrimeraComida(meal, p) {
    setMealPlan(v => ({ ...v, meals: { ...v.meals, [meal]: [...(v.meals[meal] || []), { id: uid(), foodKey: p.key, unit: p.porcion.unit, qty: p.porcion.qty }] } }));
    setNuncaRegistro(false);
    vibrar(30);
    showToast(`✅ ${p.food.name} registrado en ${meal}`);
    setRegistrarAl(null); setTab('meal'); window.scrollTo({ top: 0 });
  }
  function descartarPrimeraComida() {
    try { localStorage.setItem('jb_primera_comida_no_' + username, todayISO()); } catch {}
    setPrimeraDescartada(true);
  }

  // Prioridad de banners: solo se muestra el más relevante a la vez,
  // en vez de apilar todos. Vencimiento > Trial > Notificaciones > Instalar.
  const renewalElegible = !!(userRecord && userRecord.plan !== 'trial'
    && daysLeft(userRecord.fechaVencimiento) !== null && daysLeft(userRecord.fechaVencimiento) <= 7);
  const trialElegible = !!trialDayOf(userRecord);
  // Punto de aviso en "Inicio": solo para lo que realmente le importa al
  // alumno (su acceso/dinero) — nunca para pedirle instalar la app o
  // activar notificaciones, para que el punto siga significando algo.
  const trialDiaActual = trialDayOf(userRecord);
  const avisoInicio = renewalElegible || (trialElegible && trialDiaActual >= TRIAL_DAYS - 1);
  const [guiaVista, setGuiaVista] = useState(true);
  const [pull, setPull] = useState({ y: 0, refrescando: false });
  const pullStartY = useRef(null);
  const [mostrarEliminar, setMostrarEliminar] = useState(false);
  const [mostrarCelular, setMostrarCelular] = useState(false);
  const [mostrarNotif, setMostrarNotif] = useState(false);

  const PULL_UMBRAL = 70;
  function onPullStart(e) {
    if (window.scrollY > 4) return;
    pullStartY.current = e.touches[0].clientY;
  }
  function onPullMove(e) {
    if (pullStartY.current === null || window.scrollY > 4) return;
    const dy = e.touches[0].clientY - pullStartY.current;
    if (dy > 0) setPull(v => ({ ...v, y: Math.min(110, dy) }));
  }
  function onPullEnd() {
    if (pull.y >= PULL_UMBRAL) {
      setPull({ y: 60, refrescando: true });
      vibrar(15);
      setTimeout(() => window.location.reload(), 350);
    } else {
      setPull({ y: 0, refrescando: false });
    }
    pullStartY.current = null;
  }

  useEffect(() => {
    // Espera a que el registro real del alumno haya cargado antes de
    // decidir si falta el nombre — si se evalúa antes, userRecord aún
    // está vacío por la carga en curso y parece que no hay nombre
    // guardado, aunque sí lo haya, y la guía lo vuelve a pedir de más.
    if (!userRecord) return;
    (async () => {
      try {
        const { count } = await supabase.from('fotos_progreso')
          .select('id', { count: 'exact', head: true }).eq('username', username);
        setTieneFotos((count || 0) > 0);
      } catch (e) { alert('No se pudo completar la acción: ' + (e?.message || 'Intenta de nuevo.')); }
      try {
        const vista = localStorage.getItem('jb_guia_' + username);
        if (!vista) { setVerGuia(true); setGuiaVista(false); }
      } catch (e) { alert('No se pudo completar la acción: ' + (e?.message || 'Intenta de nuevo.')); }
    })();
  }, [username, userRecord]);

  function cerrarGuia() {
    setVerGuia(false);
    try { localStorage.setItem('jb_guia_' + username, '1'); } catch {}
  }
  const results = useMemo(() => calcAll({
    ...form,
    edad: Number(form.edad) || 0, estatura: Number(form.estatura) || 1, peso: Number(form.peso) || 0,
    cuello: Number(form.cuello) || 1, cintura: Number(form.cintura) || 1, cadera: Number(form.cadera) || 1,
  }), [form]);

  /* La meta del registro de comidas sigue sola al objetivo: al elegirlo
     o cambiarlo, o al actualizar sus datos (peso, edad...), se recalcula.
     Si la ajustó a mano en "Ajuste fino", se respeta hasta que cambie de
     objetivo. Al abrir la app solo se corrige a quien sigue con la meta
     de ejemplo (2000 kcal) sin haberla tocado nunca.                   */
  const targetsObjetivo = goalTargets(form, results.tdee);
  const metaListaPrimera = targetsObjetivo?.kcal || 0;
  const verPrimeraComida = nuncaRegistro && !primeraDescartada && alimentosHoy === 0
    && tieneDatosBasicos(form) && !!form.objetivo && metaListaPrimera > 0;
  const firmaObjetivo = targetsObjetivo
    ? [targetsObjetivo.kcal, targetsObjetivo.protein, targetsObjetivo.fat].map(Math.round).join('|') : '';
  const firmaAntes = useRef(null);
  const objetivoAntes = useRef(form.objetivo);
  useEffect(() => {
    const primera = firmaAntes.current === null;
    const cambio = !primera && firmaAntes.current !== firmaObjetivo;
    firmaAntes.current = firmaObjetivo;
    const cambioObjetivo = objetivoAntes.current !== form.objetivo;
    objetivoAntes.current = form.objetivo;
    if (!targetsObjetivo || !targetsObjetivo.kcal || !mealPlan) return;
    const m = mealPlan.macros || {};
    const deEjemplo = !mealPlan.metaManual && mealPlan.targetKcal === 2000 && m.p === 0.3 && m.c === 0.4 && m.f === 0.3;
    if (primera ? !deEjemplo : !cambio) return;
    if (mealPlan.metaManual && !cambioObjetivo) return;
    setMealPlan(v => ({ ...v, ...metaDesdeObjetivo(targetsObjetivo) }));
  }, [firmaObjetivo]);

  return (
    <div className="min-h-screen bg-zinc-950 jb-body overflow-x-hidden supports-[overflow:clip]:overflow-x-clip"
      onTouchStart={onPullStart} onTouchMove={onPullMove} onTouchEnd={onPullEnd}>
      <style>{`
        @keyframes jb-tab-fade-in { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
        .jb-tab-fade { animation: jb-tab-fade-in 0.28s ease; }
      `}</style>
      {pull.y > 0 && (
        <div className="fixed top-0 left-0 right-0 z-30 flex justify-center pointer-events-none" style={{ transform: `translateY(${Math.min(pull.y, 70) - 40}px)` }}>
          <div className="bg-zinc-900 border border-zinc-800 rounded-full p-2 shadow-lg mt-2">
            {pull.refrescando
              ? <Loader2 className="animate-spin text-orange-500" size={18} />
              : <span style={{ transform: `rotate(${Math.min(pull.y / PULL_UMBRAL, 1) * 180}deg)`, display: 'inline-block', transition: 'transform 0.1s' }}>🔄</span>}
          </div>
        </div>
      )}
      <header className="sticky top-0 z-20 border-b border-zinc-800 px-4 sm:px-6 py-3 flex items-center justify-between gap-2 bg-zinc-950/90 backdrop-blur-sm" style={{ paddingTop: 'max(0.75rem, env(safe-area-inset-top))' }}>
        <div className="flex items-center gap-2.5 min-w-0">
          <Logo />
          <BeastMascot mood={moodPorHora()} size={22} className="hidden sm:inline-block" />
        </div>
        <div className="flex items-center gap-1.5 sm:gap-3 shrink-0">
          <SoundToggleButton />
          <button onClick={() => setTab('planes')}
            className={`p-2 rounded-lg transition-colors ${tab === 'planes' ? 'text-orange-500' : 'text-zinc-500 hover:text-zinc-300'}`}
            title="Mi plan">
            <CreditCard size={18} />
          </button>
          <IndicadorGuardado estado={estadoGuardado} />
          <span className="text-zinc-500 text-sm hidden sm:inline">{username}</span>
          <button onClick={onLogout} className={btnGhost + ' px-2.5 sm:px-4'} aria-label="Salir"><LogOut size={16} /> <span className="hidden sm:inline">Salir</span></button>
        </div>
      </header>

      <div className="max-w-4xl mx-auto px-6 pt-6">
        <AvisoGuardado estado={estadoGuardado} onVolverAEntrar={onLogout} />
        {verGuia && <BienvenidaModal nombre={userRecord?.nombre} username={username} telefonoActual={userRecord?.telefono} onClose={cerrarGuia} />}
        {ofrecerNotif && !verGuia && <NotifTrasComidaModal username={username} onClose={() => setOfrecerNotif(false)} />}
        {verPrimeraComida && !verGuia && !ofrecerNotif && !ajustarMeta && (
          <PrimeraComidaModal kcalMeta={metaListaPrimera}
            onElegir={registrarPrimeraComida}
            onOtro={(meal) => { setNuncaRegistro(false); irARegistrar(meal); }}
            onCerrar={descartarPrimeraComida} />
        )}
        {tab === 'dash' && !verGuia && !ofrecerNotif && !ajustarMeta && userRecord && (
          <InvitaMomento user={userRecord} mealPlan={mealPlan} />
        )}
        {ajustarMeta && !verGuia && (
          <AjustaMetaModal faltanDatos={!tieneDatosBasicos(form)}
            onAjustar={() => { setAjustarMeta(false); setRegistrarAl(null); setTab(tieneDatosBasicos(form) ? 'goal' : 'calc'); window.scrollTo({ top: 0 }); }}
            onCerrar={() => setAjustarMeta(false)} />
        )}
        {tab === 'dash' && (
          renewalElegible ? (
            <RenewalBanner user={userRecord} onRenovar={() => setTab('planes')} />
          ) : trialElegible ? (
            <>
              <TrialBanner user={userRecord} mealPlan={mealPlan} onVerPlanes={() => setTab('planes')} />
              <RecordatorioBanner username={username} soloSiFalta />
            </>
          ) : (
            <>
              <RecordatorioBanner username={username} onEligible={setRecordatorioElegible} />
              {recordatorioElegible === false && <InstalarBanner onEligible={setInstalarElegible} />}
            </>
          )
        )}
        {tab === 'dash' && <PesajeCard form={form} setForm={setForm} />}
        {tab === 'dash' && <TuSemanaCard username={username} nombre={userRecord?.nombre} />}
      </div>

      <main key={tab} className="max-w-4xl mx-auto px-6 pb-24 jb-tab-fade">
        {tab === 'dash' && (
          <>
            <PrimerosPasos form={form} mealPlan={mealPlan} tieneFotos={tieneFotos}
              onIr={t => (t === 'registrar' ? irARegistrar(comidaDeAhora()) : setTab(t))} onVerGuia={() => setVerGuia(true)} />
            <CentroDeMando nombre={userRecord?.nombre} mealPlan={mealPlan}
              onRegistrar={irARegistrar} metaEstimada={metaEstimada}
              onAjustarMeta={() => { setTab(tieneDatosBasicos(form) ? 'goal' : 'calc'); window.scrollTo({ top: 0 }); }} />
            <ResumenSemanalCard username={username} />
            <RachaCard username={username} />
            <RepetirAyerCard username={username} mealPlan={mealPlan} setMealPlan={setMealPlan} />
            <Dashboard form={form} setForm={setForm} results={results} mealPlan={mealPlan} targets={goalTargets(form, results.tdee)} username={username} onVerComposicion={() => setTab('calc')} onIrProgreso={() => { setTab('progress'); window.scrollTo({ top: 0 }); }} />
          </>
        )}
        {(tab === 'calc' || tab === 'goal') && (
          <CuerpoTab form={form} setForm={setForm} results={results} mealPlan={mealPlan} setMealPlan={setMealPlan} vistaInicial={tab === 'goal' ? 'objetivo' : 'composicion'} onIrComidas={() => { setTab('meal'); window.scrollTo({ top: 0 }); }} />
        )}
        {tab === 'meal' && <MealTab mealPlan={mealPlan} setMealPlan={setMealPlan} tdee={results.tdee} targets={goalTargets(form, results.tdee)} username={username} reconocimientoFotoHasta={userRecord?.reconocimientoFotoHasta} hojaInicial={registrarAl} />}
        {(tab === 'progress' || tab === 'photos') && (
          <ProgressTab username={username} form={form} setForm={setForm} nombre={userRecord?.nombre} vistaInicial={tab === 'photos' ? 'fotos' : 'tendencias'} />
        )}
        {tab === 'planes' && <PlanesTab username={username} nombre={userRecord?.nombre} userRecord={userRecord} />}
      </main>
      <footer className="text-center py-4 pb-28 flex items-center justify-center gap-3 flex-wrap">
        <a href="https://jonahbeast.com/privacidad.html" target="_blank" rel="noopener noreferrer"
          className="jb-body text-[11px] text-zinc-700 hover:text-zinc-500 underline">
          Política de Privacidad
        </a>
        <span className="text-zinc-800 text-[11px]">·</span>
        <button onClick={() => setMostrarNotif(true)}
          className="jb-body text-[11px] text-zinc-700 hover:text-orange-400 underline">
          Activar notificaciones
        </button>
        <span className="text-zinc-800 text-[11px]">·</span>
        <button onClick={() => setMostrarCelular(true)}
          className="jb-body text-[11px] text-zinc-700 hover:text-orange-400 underline">
          {userRecord?.telefono ? 'Actualizar mi celular' : 'Agregar mi celular'}
        </button>
        <span className="text-zinc-800 text-[11px]">·</span>
        <button onClick={() => setMostrarEliminar(true)}
          className="jb-body text-[11px] text-zinc-700 hover:text-red-400 underline">
          Eliminar mi cuenta
        </button>
      </footer>
      {mostrarNotif && (
        <NotificacionesModal username={username} onClose={() => setMostrarNotif(false)} />
      )}
      {mostrarCelular && (
        <MiCelularModal username={username} telefonoActual={userRecord?.telefono} onClose={() => setMostrarCelular(false)} />
      )}
      {mostrarEliminar && (
        <EliminarCuentaModal username={username} onClose={() => setMostrarEliminar(false)} onEliminado={onLogout} />
      )}
      <WhatsAppButton />
      <nav className="fixed bottom-0 left-0 right-0 z-30 bg-zinc-950 border-t border-zinc-800 flex"
        style={{ paddingBottom: 'env(safe-area-inset-bottom)' }}>
        {[
          { id: 'dash', icon: LayoutDashboard, label: 'Inicio', activo: tab === 'dash', aviso: avisoInicio },
          { id: 'meal', icon: Salad, label: 'Comidas', activo: tab === 'meal' },
          { id: 'calc', icon: Flame, label: 'Mi cuerpo', activo: tab === 'calc' || tab === 'goal' },
          { id: 'progress', icon: TrendingUp, label: 'Progreso', activo: tab === 'progress' || tab === 'photos' },
        ].map(item => (
          <button key={item.id} onClick={() => { setRegistrarAl(null); setTab(item.id); }}
            className={`flex-1 flex flex-col items-center justify-center gap-0.5 py-2.5 transition-colors ${item.activo ? 'text-orange-500' : 'text-zinc-500'}`}>
            <span className="relative">
              <item.icon size={20} strokeWidth={item.activo ? 2.5 : 2} />
              {item.aviso && <span className="absolute -top-0.5 -right-0.5 w-2 h-2 rounded-full bg-orange-500" />}
            </span>
            <span className="jb-body text-[10px]">{item.label}</span>
          </button>
        ))}
      </nav>
    </div>
  );
}

export {
  StudentDashboard,
};
